export const NAMESPACE = "https://jana.dev/contracts/";

function lookup(name: string): ValidateFunction {
  const key = name.startsWith(NAMESPACE) ? name.slice(NAMESPACE.length) : name;
  const validate = validators[key];
  if (!validate) throw new Error(`unknown contract ${name}`);
  return validate;
}

/** Every violation as "<instance path>: <message>", in a stable order. */
export function errors(name: string, data: unknown): string[] {
  const validate = lookup(name);
  if (validate(data)) return [];
  return (validate.errors ?? []).map((e) => `${e.instancePath || "$"}: ${e.message ?? e.keyword}`).sort();
}

export function isValid(name: string, data: unknown): boolean {
  return lookup(name)(data);
}
